def write_ppm(path, w, h, pixels):
    """Write a binary (P6) Netpbm PPM file."""
    with open(path, "wb") as f:
        f.write(f"P6\n{w} {h}\n255\n".encode("ascii"))
        for row in pixels:
            for (r, g, b) in row:
