#!/usr/bin/env python3
"""Minimal little-endian classic TIFF tag reader (no deps)."""
import struct
import sys


def read_tiff(path):
    with open(path, "rb") as f:
        data = f.read()
    if data[:2] != b"II":
        raise ValueError("not little-endian")
    if struct.unpack("<H", data[2:4])[0] != 42:
        raise ValueError("bad magic")
    ifd_off = struct.unpack("<I", data[4:8])[0]
    num = struct.unpack("<H", data[ifd_off:ifd_off + 2])[0]
    tags = {}
    for i in range(num):
        e = ifd_off + 2 + i * 12
        tag, typ, cnt = struct.unpack("<HHI", data[e:e + 8])
        val_off = e + 8
        types = {1: (1, 1), 2: (1, 1), 3: (2, 1), 4: (4, 1), 5: (4, 1), 6: (1, 1), 7: (1, 1), 8: (2, 1), 9: (4, 1), 10: (4, 1), 11: (4, 1)}
        size, count_size = types.get(typ, (4, 1))
        total = size * cnt
        if total <= 4:
            raw = data[val_off:val_off + 4]
        else:
            off = struct.unpack("<I", data[val_off:val_off + 4])[0]
            raw = data[off:off + total]
        fmt = {1: "B", 2: "c", 3: "H", 4: "I", 5: "II", 6: "b", 7: "B", 8: "h", 9: "i", 10: "ii", 11: "i"}[typ]
        fmt = "<" + fmt
        vals = list(struct.unpack("<" + str(cnt) + fmt, raw)) if fmt != "<c" else [raw[0]] * cnt
        tags[tag] = (typ, cnt, vals)
    next_off = struct.unpack("<I", data[ifd_off + 2 + num * 12:ifd_off + 2 + num * 12 + 4])[0]
    return tags, next_off, len(data)


def dump(path):
    tags, nxt, size = read_tiff(path)
    print(f"== {path} (file size {size}, next ifd {nxt})")
    for tag in sorted(tags):
        typ, cnt, vals = tags[tag]
        print(f"  tag {tag} (0x{tag:04X}): type {typ}, count {cnt}, values {vals}")


if __name__ == "__main__":
    for p in sys.argv[1:]:
        dump(p)

